('axstc', 'Fields', 'structcaption', 'Form/Report', 'c', 150, 0, 'select', NULL, NULL, NULL, NULL, 'select cast (caption as varchar(100) ) as caption,name,ord,ttype from (
select ''ALL Forms'' as caption,''ALL Forms'' as name,0 as ord,''Tstruct'' as ttype from dual where :alltrstruct = ''T'' 
and :propvalue1 not in(''html pages'',''html templates'')
union
select ''ALL Reports'' as caption,''ALL Reports'' as name,0 as ord,''Iview'' as ttype from dual  where :alliviews = ''T''
and :propvalue1 not in(''html pages'',''html templates'')
union
select caption||''(''||name||'')'' as caption,name,1,''Tstruct'' as ttype  from tstructs where ( :setype = ''Tstruct'' or :setype = ''All'')
and :propvalue1 not in(''html pages'',''html templates'')
union
select caption||''(''||name||'')'' as caption,name,2 ,''Iview'' as ttype from iviews where ( :setype = ''Iview'' or :setype = ''All'')
and :propvalue1 not in(''html pages'',''html templates'')
union
select caption||''(''||name||'')'' as caption,name,3,''Page'' as ttype from axpages where ( :setype = ''Page'' or :setype = ''All'') and 1=2
union
select title||''(''||cast(widget_id as varchar)||'')'', cast(widget_id as varchar) as name,4,''Widget'' as ttype  from ax_widget  where ( :setype = ''Widget'' or :setype = ''All'')
union
select caption||''(''||name||'')'' as caption,name,3,''html pages'' as ttype from axpages 
where :propvalue1 = ''html pages'' 
and pagetype =''web'' 
) a
order by 3,1
