ate_trunc(''month'',current_date) </a11><a5>0</a5><a12>False</a12><a14>False</a14><a56></a56><a13>Accept</a13><a15/><a67>325</a67><a68>false</a68></pfdate><ptdate cat="params" ord="2"><a1>Task1</a1><a0>ptdate</a0><a2>To</a2><a4>Date/Time</a4><a9>False</a9><a6 sugg="false">date()</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>False</a12><a14>False</a14><a56></a56><a13>Accept</a13><a15/><a67>325</a67><a68>false</a68></ptdate><hyperlinks cat="hyperlinks"><exl sname="iprnfail" source="actn" pop="False" refresh="False" load="True"><p1 n="pjobid" v=":id"/></exl></hyperlinks><row1 cat="sql"><a1>Task1</a1><a2><l0>select id,calledon,username,act_script_name,axprintdefname,axprintwhat,</l0><l1>case when axprintwhat in(''Form Data'')  then b.caption </l1><l2>when axprintwhat in(''IView'',''Form Data from IView'') then i.caption</l2><l3>when axprintwhat in(''Form data from SQL'',''SQL Result'') then ''SQL'' end source,</l3><l4>axprintformnames,axprintsaveto,status,''View details'' actn</l4><l5>from axprintdetails a</l5><l6>left join tstructs  b on a.axprinttransid = b."name" </l6><l7>left join iviews i on a.axprintiviewname = i.name</l7><l8>where a.calledon between :pfdate and :ptdate</l8><l9>order by calledon desc,id</l9></a2><a3></a3><a4>reportsql</a4></row1></root>', 1, '16/04/2021 07:51:15', '15/04/2021 22:10:00', '26-06-2025 14:40:10', 'admin', 'admin', 'admin', NULL, NULL),
