lnum="6"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>if acttype = 1</l0><l1>LoadFormAndData({ad_am},{axpdef_peg_actorid=:axpdef_peg_actorid},{d},{false})</l1><l2>else</l2><l3>LoadFormanddata({ad_at},{axpdef_peg_actorid=:axpdef_peg_actorid},{d},{false})</l3><l4>end</l4></exprset></param1></r1></act1></scripts><comps cat="comps" dwbtb="true" LocalNum="9" btn="3" vupd="" pnlheight="35"><btn1 key="btn7" caption="New" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="new" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="New" down=""><icon><text>add</text><addClass>material-icons</addClass></icon></btn1><btn2 key="btn8" caption="Remove" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="delete" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Remove" down=""><icon><text>remove</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btnTask" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="false" footer="false" folder="true" hint="Tasks" down=""><icon><text>fact_check</text><addClass>material-icons</addClass></icon></btn3><x__head caption="Assign users to actors" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select case when b.acttype=1 then b.actorname </l0><l1>when acttype=2 then concat(b.process,'','',b.taskname) else null end processdtl ,b.axpdef_peg_actorid,</l1><l2>case when assignmodecnd!=0 then </l2><l3>case when b.assignmodecnd = 1 then b.defusername  </l3><l4>when b.assignmodecnd = 2 then c.ugrps</l4><l5>when b.assignmodecnd = 3 then d.dgrps</l5><l6>end else ''Assign users'' end users,acttype,</l6><l7>''&lt;b&gt;Created by&lt;/b&gt; ''||b.createdby||'' on ''||b.createdon||''&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;''||b.username||'' on ''||b.modifiedon updated</l7><l8>from axpdef_peg_actor b</l8><l9>left join (select axpdef_peg_actorid,string_agg(ugrpusername,'','') ugrps from axpdef_peg_actorusergrp group by axpdef_peg_actorid) c</l9><l10>on b.axpdef_peg_actorid=c.axpdef_peg_actorid</l10><l11>left join (select axpdef_peg_actorid,string_agg(datagrpusers,'','') dgrps from axpdef_peg_grpfilter group by axpdef_peg_actorid)d</l11><l12>on b.axpdef_peg_actorid=d.axpdef_peg_actorid</l12><l13>order by 1</l13></a2><a3></a3><a4>reportsql</a4></row1><processdtl cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>processdtl</a2><a3>Actor name</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>349</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55>act1</a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></processdtl><users cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>users</a2><a3>Users</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>634</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></users><updated cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>updated</a2><a3>Created/Modified</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>339</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></updated><acttype cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>acttype</a2><a3>acttype</a3><a1>Task1</a1><a4>Numeric</a4><a5>0</a5><a6></a6><a7>false</a7><a8>false</a8><a21>true</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>false</a16><a17>79</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></acttype><axpdef_peg_actorid cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>axpdef_peg_actorid</a2><a3>axpdef_peg_actorid</a3><a1>Task1</a1><a4>Numeric</a4><a5>0</a5><a6></a6><a7>false</a7><a8>false</a8><a21>true</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>false</a16><a17>121</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></axpdef_peg_actorid><hyperlinks cat="hyperlinks"><ldactgr sname="tad__g" source="actgroup" pop="False" refresh="False" load="True"><p1 n="axpdef_peg_groupID" v=":axpdef_peg_groupid"/></ldactgr><ldac sname="tad_at" source="users" pop="False" refresh="False" load="True"><p1 n="axpdef_peg_actorID" v=":axpdef_peg_actorid"/></ldac><lact sname="tad_am" source="actorname" pop="False" refresh="False" load="True"><p1 n="axpdef_peg_actorID" v=":axpdef_peg_actorid"/></lact></hyperlinks><temp><iviewcaption>Assign users to actors</iviewcaption><menupos>Default</menupos><menupath></menupath><defpage>t</de