union 
select ''Failed'' pstatus from dual
order by pstatus</a11><a5>0</a5><a12>False</a12><a14>False</a14><a56></a56><a13>Accept</a13><a15/></pstatus><ptransid cat="params" ord="3"><a1>Task1</a1><a0>ptransid</a0><a2>Transid</a2><a4>Character</a4><a9>False</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>False</a12><a14>False</a14><a56>ALL</a56><a13>Accept</a13><a15/></ptransid><pfilename cat="params" ord="4"><a1>Task1</a1><a0>pfilename</a0><a2>File Name</a2><a4>Character</a4><a9>False</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>False</a12><a14>False</a14><a56>ALL</a56><a13>Accept</a13><a15/></pfilename><row1 cat="sql"><a1>Task1</a1><a2><l0>  SELECT filename,</l0><l1>         recdon,</l1><l2>         transid,</l2><l3>         tstructname,</l3><l4>         instatus</l4><l5>    FROM ax_inbound_status</l5><l6>   WHERE indate = :asondt</l6><l7>         AND ( (instatus NOT LIKE ''%No of Records not imported : 0%''</l7><l8>                AND :pstatus = ''Failed'')</l8><l9>              OR :pstatus = ''ALL'')</l9><l10>         AND (transid LIKE ''%'' || :ptransid || ''%'' OR :ptransid = ''ALL'')</l10><l11>         AND (filename LIKE ''%'' || :pfilename || ''%'' OR :pfilename = ''ALL'')</l11><l12>ORDER BY recdon DESC</l12></a2><a3></a3><a4>reportsql</a4></row1></root>', 1, '19/06/2019 00:00:00', '02/07/2015 00:00:00', '26-06-2025 14:40:37', 'admin', 'admin', 'admin', NULL, NULL),
('ad___fpr', 'Form components', '<root pform="yes" name="ad___fpr" caption="Form components" updatedon="03/06/2025 09:07:46" updatedby="admin" updusername="" dbtype="postgre" importedon="10/09/2025 12:01:11" importedby="admin" createdon="" createdby=""><iview cat="iview" hideprojname="F" hidereportdate="F" parrange="1"><a0>ad___fpr</a0><a2>Form components</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>false</a11><a12></a12><a13></a13><a14></a14><a15></a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>true</a63><a64>false</a64><b9>ad___fpr</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>1</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39>None</b39><a65>false</a65><a66>false</a66></iview><scripts cat="actions"><act1 script="true" cap="act1" type="iview" apply="" applyon="" sname="ad___fpr" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="2"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>{T}</l0></exprset></param1></r1></act1><addrule script="true" cap="addrule" type="iview" apply="" applyon="" sname="ad___fpr" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="2"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="