</l0><l1>concat(case when a.runtimetstruct=''T'' then ''Runtime form'' else ''Developer form'' end||''&lt;/br&gt;'',</l1><l2>case when length(t.purpose) &gt; 3 then purpose||''&lt;/br&gt;'' else '''' end,</l2><l3>(select pr_utl_forms_menutree(concat(''t'',a.name))),</l3><l4>coalesce ( case when length(t.savectrlfld) &gt; 1 then ''Save control field- ''||t.savectrlfld ||''&lt;/br&gt;'' end,''''),</l4><l5>coalesce (case when t.delctrlfld is not null then ''Delete control field- ''|| t.delctrlfld ||''&lt;/br&gt;'' end,''''),</l5><l6>case when coalesce(oq.oqns,0 ) != 0 then  oq.oqns|| '' Outbound queues''||'','' else '''' end,</l6><l7>case when coalesce(b.cnt,0 ) != 0 then  b.cnt ||'' Rules defined''|| '','' else '''' end,</l7><l8>case when coalesce(p.pros,0 ) != 0 then  p.pros||'' Process defined''|| '','' else '''' end,</l8><l9>case when coalesce(ap.aps,0 ) != 0 then  ap.aps||'' Auto prints''||'','' else '''' end,</l9><l10>case when coalesce(fn.fns,0 ) != 0 then  fn.fns||'' Form notifications''||'','' else '''' end)</l10><l11>as form_properties,concat(case when a.runtimetstruct=''T'' then concat(''script3,Edit form,script,edit~'')  else null end,</l11><l12>case when a.runtimemod =''T'' then concat(''ruleeng,'',case when b.cnt&gt;0 then ''View rules'' else ''Add rule'' end,'',script,rule~'') end,</l12><l13>case when p.pros &gt; 0 then concat(''peg,'',''Process listing'','',script,schema~'') else concat(''newpeg,'',''Add process definition'','',script,schema~'') end,</l13><l14>concat(''autoprint,'',case when ap.aps&gt;0 then ''View AutoPrints'' else ''Add AutoPrints'' end,'',script,print~''),</l14><l15>concat(''formnot,'',case when fn.fns&gt;0 then ''View Notifications'' else ''Add Notifications'' end,'',script,notifications_active~''),</l15><l16>concat(''queue,'',case when oq.oqns&gt;0 then ''Queue listing'' else ''Add to Outbound queue'' end,'',script,playlist_add~''),</l16><l17>''condata,Connected forms,script,call_merge'') AxRowOptions,</l17><l18>b.cnt rules,p.pros processes,ap.aps autopr,fn.fns fnotify,oq.oqns queue,''Form'' fptype,</l18><l19>''&lt;b&gt;Created by &lt;/b&gt;''||a.createdby||'' on ''||a.createdon||''&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;''||a.updatedby||'' on ''||a.updatedon updated</l19><l20>from tstructs a</l20><l21>left outer join axptstructs t on a.name = t.tstruct</l21><l22>left outer join (select  b.stransid, count(1) as cnt from axpdef_ruleeng b group by stransid) b on ( a.name = b.stransid )</l22><l23>left outer join (select transid,count(distinct processname) pros from axprocessdefv2 a  group by transid) p on ( a.name = p.transid )</l23><l24>left outer join (select stransid,count(1) aps from AxAutoPrints  group by stransid) ap on ( a.name = ap.stransid)</l24><l25>left outer join (select stransid,count(1) fns from AxFormNotify  group by stransid) fn on ( a.name = fn.stransid)</l25><l26>left outer join (select stransid,count(1) oqns from AxOutQueues group by stransid) oq on ( a.name = oq.stransid)</l26><l27> order by fn_utl_forms_dateconversion(a.updatedon) desc</l27></a2><a3></a3><a4>reportsql</a4></row1><axpdef_tstructid cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>axpdef_tstructid</a2><a3>axpdef_tstructid</a3><a1>Task1</a1><a4>Numeric</a4><a5>0</a5><a6></a6><a7>false</a7><a8>false</a8><a21>true</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>false</a16><a17>187</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></axpdef_tstructid><editable cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>editable</a2><a3></a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>true</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a