and (exists(select 1 from unnest(string_to_array(usergroups,'','')) val where val =(:pusergroup))or ''All'' = :pusergroup)
and (exists(select 1 from unnest(string_to_array(actors,'','')) val where val =(:pactors))or ''All'' = :pactors)
order by 2
